return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'English (United States)','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 17:37+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'en_US','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Translate','Lingua Forge — Quick Translate'=>'Lingua Forge — Quick Translate','Informative'=>'Informative','Persuasive'=>'Persuasive','Storytelling'=>'Storytelling','Technical'=>'Technical','Conversational'=>'Conversational','Permission denied.'=>'Permission denied.','Cannot determine target language from slug.'=>'Cannot determine target language from slug.','Invalid post type.'=>'Invalid post type.','Invalid or primary language.'=>'Invalid or primary language.','Template not found or not stored in the database.'=>'Template not found or not stored in the database.','Template has no content.'=>'Template has no content.','No internal links found to update.'=>'No internal links found to update.','%d link updated.'=>'%d link updated.' . "\0" . '%d links updated.','No language-specific template parts found to map.'=>'No language-specific template parts found to map.','No template part references needed updating.'=>'No template part references needed updating.','%d part reference updated.'=>'%d part reference updated.' . "\0" . '%d part references updated.','Invalid language.'=>'Invalid language.','Template part not found or not stored in the database.'=>'Template part not found or not stored in the database.','Template part has no content.'=>'Template part has no content.','No navigation references needed updating.'=>'No navigation references needed updating.','%d navigation reference updated.'=>'%d navigation reference updated.' . "\0" . '%d navigation references updated.','No AI provider configured.'=>'No AI provider configured.','Missing pattern name or language.'=>'Missing pattern name or language.','Pattern not found.'=>'Pattern not found.','Pattern has no content to translate.'=>'Pattern has no content to translate.','AI provider returned an empty response.'=>'AI provider returned an empty response.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.','Invalid template type.'=>'Invalid template type.','Template "%s" already exists.'=>'Template "%s" already exists.','"%s" created.'=>'"%s" created.','Invalid template part.'=>'Invalid template part.','Template part "%s" already exists.'=>'Template part "%s" already exists.','"%1$s" created. %2$d template updated.'=>'"%1$s" created. %2$d template updated.' . "\0" . '"%1$s" created. %2$d templates updated.','Page'=>'Page','Single'=>'Single','Search'=>'Search','Search Results'=>'Search Results','Archive'=>'Archive','Front Page'=>'Front Page','Single: %s'=>'Single: %s','Single %s'=>'Single %s','Archive: %s'=>'Archive: %s','%s Archive'=>'%s Archive','No source content found to translate.'=>'No source content found to translate.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.','Navigation not found.'=>'Navigation not found.','Navigation has no content to translate.'=>'Navigation has no content to translate.','"%1$s %2$s" saved.'=>'"%1$s %2$s" saved.','Translate page…'=>'Translate page…','Generate content…'=>'Generate content…','AI Behaviour Preset'=>'AI Behaviour Preset','Custom'=>'Custom','Global default (%s)'=>'Global default (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.','Close'=>'Close','Translate missing'=>'Translate missing','From'=>'From','Retranslate'=>'Retranslate','Translating…'=>'Translating…','Retranslating…'=>'Retranslating…','✓ Done'=>'✓ Done','Error'=>'Error','Navigation posts are translated via the Router tab, not this button.'=>'Navigation posts are translated via the Router tab, not this button.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.','No %s version found in this translation group.'=>'No %s version found in this translation group.','AI Usage'=>'AI Usage','Today'=>'Today','Last 7 days'=>'Last 7 days','Last 30 days'=>'Last 30 days','All time'=>'All time','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'No AI usage recorded in the selected window (%s). Pick a wider range above.','Feature'=>'Feature','Provider'=>'Provider','Model'=>'Model','Requests'=>'Requests','Input tokens'=>'Input tokens','Output tokens'=>'Output tokens','Total tokens'=>'Total tokens','Total'=>'Total','API Keys'=>'API Keys','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.','API Key'=>'API Key','Paste your API key…'=>'Paste your API key…','✓ Configured'=>'✓ Configured','✗ Not configured'=>'✗ Not configured','Test connection'=>'Test connection','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Leave blank to keep the existing key. Enter a new value to replace it.','Remove stored key'=>'Remove stored key','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.','environment variable'=>'environment variable','PHP constant'=>'PHP constant','Alternative (server-side):'=>'Alternative (server-side):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'You can also define keys as constants or environment variables (e.g., in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:','Unknown provider.'=>'Unknown provider.','No API key configured for this provider.'=>'No API key configured for this provider.','Could not instantiate the provider.'=>'Could not instantiate the provider.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Provider returned no text. Check the WordPress error log for the detailed failure reason.','Behavior'=>'Behavior','Block Editor'=>'Block Editor','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.','Block locking'=>'Block locking','Allow editors to lock individual blocks'=>'Allow editors to lock individual blocks','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.','Template mode'=>'Template mode','Allow Gutenberg template-editing mode on post screens'=>'Allow Gutenberg template-editing mode on post screens','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.','Compliance Preset'=>'Compliance Preset','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.','Global AI preset'=>'Global AI preset','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per feature','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.','Technical / Scientific instructions'=>'Technical / Scientific instructions','Legal / Compliance instructions'=>'Legal / Compliance instructions','Creative / Marketing instructions'=>'Creative / Marketing instructions','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Leave blank to use the built-in default. Clearing a saved override restores the default on next save.','View built-in default'=>'View built-in default','Translation Memory'=>'Translation Memory','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.','Enable block-level translation cache reuse across posts'=>'Enable block-level translation cache reuse across posts','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.','General'=>'General','Light'=>'Light','Meta Description, Excerpt Generator'=>'Meta Description, Excerpt Generator','Quality'=>'Quality','Translation, Content Generator'=>'Translation, Content Generator','Active Provider'=>'Active Provider','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Currently inherited from the %s constant. Selecting a value here will override it.','Models'=>'Models','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.','active'=>'active','overridden'=>'overridden','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: to reset a model to the built-in default, clear the field and save.','Glossary'=>'Glossary','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.','Glossary entry added.'=>'Glossary entry added.','Glossary entry removed.'=>'Glossary entry removed.','Could not add entry: source term and target term are required.'=>'Could not add entry: source term and target term are required.','Could not save the glossary entry.'=>'Could not save the glossary entry.','Source language'=>'Source language','— Any —'=>'— Any —','Target language'=>'Target language','— Any target —'=>'— Any target —','Filter'=>'Filter','Reset'=>'Reset','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'No glossary entries yet. Add one below to start enforcing terminology in translations.','Source term'=>'Source term','Target term'=>'Target term','Source lang'=>'Source lang','Target lang'=>'Target lang','Notes'=>'Notes','any'=>'any','Delete this glossary entry?'=>'Delete this glossary entry?','Delete'=>'Delete','Add new entry'=>'Add new entry','The phrase as it appears in the source text.'=>'The phrase as it appears in the source text.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.','— Any source language —'=>'— Any source language —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.','— Any target language —'=>'— Any target language —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").','Add entry'=>'Add entry','Limits'=>'Limits','Authors and above (edit_published_posts)'=>'Authors and above (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Contributors and above — default (edit_posts)','Editors and above (edit_others_posts)'=>'Editors and above (edit_others_posts)','Administrators only (manage_options)'=>'Administrators only (manage_options)','AI Limits & Security'=>'AI Limits & Security','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.','Daily request limit'=>'Daily request limit','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.','Minimum role'=>'Minimum role','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.','Translation Limits'=>'Translation Limits','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.','Model tier'=>'Model tier','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Quality (default — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Light (fast and cost-effective — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.','Max output tokens'=>'Max output tokens','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.','Max input characters'=>'Max input characters','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.','Quick Translation'=>'Quick Translation','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.','Light (default — fast and cost-effective)'=>'Light (default — fast and cost-effective)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Quality (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximum tokens the AI may produce per quick translation. Default: 2 000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximum characters accepted from the input field. Default: 8 000.','Content Generator'=>'Content Generator','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.','Max hints characters'=>'Max hints characters','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximum characters read from the Hints field. Default: 2 000.','Max context characters'=>'Max context characters','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.','Maintenance'=>'Maintenance','Language Overrides'=>'Language Overrides','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.','Override file uploaded successfully.'=>'Override file uploaded successfully.','Override file deleted.'=>'Override file deleted.','No file was selected.'=>'No file was selected.','Only .mo files are accepted.'=>'Only .mo files are accepted.','The upload failed — please try again.'=>'The upload failed — please try again.','Could not save the file. Check that the uploads folder is writable.'=>'Could not save the file. Check that the uploads folder is writable.','Invalid filename.'=>'Invalid filename.','Security check failed — file path is not permitted.'=>'Security check failed — file path is not permitted.','An unknown error occurred.'=>'An unknown error occurred.','Text domain / locale'=>'Text domain / locale','Files'=>'Files','Size'=>'Size','Delete all files for this override (both .mo and .po)?'=>'Delete all files for this override (both .mo and .po)?','No override files uploaded yet.'=>'No override files uploaded yet.','Upload .mo file'=>'Upload .mo file','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.','Upload Override'=>'Upload Override','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copy to Safe Storage','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.','File copied to safe storage successfully.'=>'File copied to safe storage successfully.','Source file not found.'=>'Source file not found.','Could not copy the file. Check that the uploads folder is writable.'=>'Could not copy the file. Check that the uploads folder is writable.','Invalid file reference.'=>'Invalid file reference.','Type'=>'Type','✓ In safe storage'=>'✓ In safe storage','Copy to safe storage'=>'Copy to safe storage','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.','AI Cache'=>'AI Cache','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.','AI cache cleared. %d entry was removed.'=>'AI cache cleared. %d entry was removed.' . "\0" . 'AI cache cleared. %d entries were removed.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.','Clear AI Cache'=>'Clear AI Cache','Debug Files'=>'Debug Files','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.','Debug files cleared. %d file was removed.'=>'Debug files cleared. %d file was removed.' . "\0" . 'Debug files cleared. %d files were removed.','Debug logging enabled.'=>'Debug logging enabled.','Debug logging disabled.'=>'Debug logging disabled.','Debug logging'=>'Debug logging','Write AI prompts and responses to disk for troubleshooting'=>'Write AI prompts and responses to disk for troubleshooting','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.','Currently:'=>'Currently:','✓ Enabled'=>'✓ Enabled','✗ Disabled'=>'✗ Disabled','Directory'=>'Directory','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filter with linguaforge_debug_dir to redirect debug output to a non-public location.','.txt file(s) in the directory'=>'.txt file(s) in the directory','Save Debug Setting'=>'Save Debug Setting','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.','Clear Debug Files'=>'Clear Debug Files','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).','Translation Memory cleared. %d cached block was removed.'=>'Translation Memory cleared. %d cached block was removed.' . "\0" . 'Translation Memory cleared. %d cached blocks were removed.','Status'=>'Status','— toggle in Settings → Behavior.'=>'— toggle in Settings → Behavior.','Cached blocks'=>'Cached blocks','Cumulative cache hits'=>'Cumulative cache hits','(avg %.1f hits/block)'=>'(avg %.1f hits/block)','Oldest entry'=>'Oldest entry','Newest entry'=>'Newest entry','Approximate size'=>'Approximate size','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Clear the entire Translation Memory? Future translations will rebuild the cache as they run.','Clear Translation Memory'=>'Clear Translation Memory','Uninstall Behaviour'=>'Uninstall Behaviour','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.','Uninstall setting saved.'=>'Uninstall setting saved.','Delete content data on uninstall'=>'Delete content data on uninstall','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled','Warning:'=>'Warning:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.','Save Uninstall Setting'=>'Save Uninstall Setting','Router'=>'Router','Primary language saved.'=>'Primary language saved.','Permalink rules flushed successfully.'=>'Permalink rules flushed successfully.','Primary Language'=>'Primary Language','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.','Primary language'=>'Primary language','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'After changing the primary language, flush permalinks (section below) for the URL routing to update.','URL structure'=>'URL structure','Path prefix — example.com/de/'=>'Path prefix — example.com/de/','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Subdomain mode requires your web server to point all language subdomains (e.g., de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g., www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.','Browser language redirect'=>'Browser language redirect','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirect visitors to their preferred language based on the browser\'s Accept-Language header','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.','Save Router Settings'=>'Save Router Settings','Flush Permalinks'=>'Flush Permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.','Flush Permalink Rules'=>'Flush Permalink Rules','Active Languages'=>'Active Languages','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Languages currently known to 